insert into public.questions (id, category, status, data) values
  ('q-travel-0001', 'สถานที่ท่องเที่ยว', 'draft', $j${"id":"q-travel-0001","category":"สถานที่ท่องเที่ยว","topic":"ภูทับเบิก","answer":"TH6704","cards":[{"type":"image","role":"main","tag_hint":null,"src":"img/q-travel-0001.webp","credit":"Kriengsak Jirasirirojanakorn","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0","source_url":"https://commons.wikimedia.org/wiki/File:Phu_Thap_Boek_1.jpg","focus":"50% 50%","source":"commons"},{"type":"text","role":"hint","text":"อยู่ภาคกลางตอนบนสุด (ตามการแบ่ง 6 ภาค) ในจังหวัดที่ติดกับเลยและพิษณุโลก","tag_hint":"region"},{"type":"text","role":"hint","text":"ยอดเขาสูงราว 1,768 เมตร สูงที่สุดของจังหวัด มีไร่กะหล่ำปลีขั้นบันไดของชุมชนชาวม้ง","tag_hint":"terrain"},{"type":"text","role":"hint","text":"ได้ฉายา “ดาวบนดิน” อยู่ในอำเภอทางเหนือของจังหวัด ที่ชื่ออำเภอบอกว่าเป็นเมืองหล่มเดิม","tag_hint":"district"}],"reveal":{"image":{"src":"img/q-travel-0001.webp","file":"Phu Thap Boek 1.jpg","credit":"Kriengsak Jirasirirojanakorn","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0","source_url":"https://commons.wikimedia.org/wiki/File:Phu_Thap_Boek_1.jpg","focus":"50% 50%","modified":"ย่อขนาดและแปลงเป็น WebP","source":"commons"},"facts":{"ชื่อ":"ภูทับเบิก","ที่ตั้ง":"ตำบลวังบาล อำเภอหล่มเก่า จังหวัดเพชรบูรณ์","จุดเด่น":"ยอดเขาสูงที่สุดของจังหวัด ราว 1,768 เมตร อากาศเย็นตลอดปี ทะเลหมอกยามเช้า และไร่กะหล่ำปลีขั้นบันได · ฉายา “ดาวบนดิน” จากแสงไฟบ้านเรือนยามค่ำ","ช่วงที่เหมาะไป":"ปลายฝนต้นหนาวถึงฤดูหนาว ช่วงเช้ามีโอกาสเห็นทะเลหมอก (ธันวาคมอากาศหนาวมาก)","ความเป็นมา":"พื้นที่เกษตรบนที่สูงของชุมชนชาวม้ง ที่ปลูกผักและเปิดรับนักท่องเที่ยว"},"reasoning":"ทะเลหมอก + ไร่ผักขั้นบันได → ภูเขาสูง · ภาคกลางตอนบนสุด → เพชรบูรณ์ · ยอดเขาของชาวม้งทางเหนือของจังหวัด → อ.หล่มเก่า","sources":[{"title":"ไทยรัฐ: ภูทับเบิก ต.วังบาล อ.หล่มเก่า สูง 1,768 ม.","url":"https://www.thairath.co.th/lifestyle/travel/2859701"},{"title":"KTC: ไร่กะหล่ำปลีขั้นบันได ช่วงเวลาที่เหมาะไป","url":"https://www.ktc.co.th/article/travel-guide/thailand/phu-thap-buek-attractions"},{"title":"ไทยรัฐ: ฉายา “ดาวบนดิน”","url":"https://www.thairath.co.th/lifestyle/travel/2821177"},{"title":"ไทยพีบีเอส: ชาวม้งภูทับเบิก ปลูกผักปลอดสารพิษ","url":"https://www.thaipbs.or.th/program/WanmaiVariety/watch/k0lZf5"}]},"schedule_date":null,"verified_by":null,"verified_at":null,"note":"ร่าง V2 — เปลี่ยนคำตอบเป็นระดับอำเภอ ข้อมูลค้นจากแหล่งที่ระบุ รอทีมตรวจทาน","status":"draft","published_at":null}$j$::jsonb),
