  ('q-travel-0008', 'สถานที่ท่องเที่ยว', 'draft', $j${"id":"q-travel-0008","category":"สถานที่ท่องเที่ยว","topic":"เขาตะปู (เกาะเจมส์บอนด์)","answer":"TH8204","cards":[{"type":"image","role":"main","tag_hint":null,"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/Phang_Nga_Bay%2C_Koh_Tapu%2C_Thailand.jpg/1280px-Phang_Nga_Bay%2C_Koh_Tapu%2C_Thailand.jpg","credit":"Vyacheslav Argenberg","license":"CC BY 4.0","license_url":"https://creativecommons.org/licenses/by/4.0","source_url":"https://commons.wikimedia.org/wiki/File:Phang_Nga_Bay,_Koh_Tapu,_Thailand.jpg","focus":"30% 50%","source":"commons"},{"type":"text","role":"hint","text":"อยู่ภาคใต้ฝั่งทะเลอันดามัน ในจังหวัดที่อยู่ติดเกาะภูเก็ตทางทิศเหนือ","tag_hint":"region"},{"type":"text","role":"hint","text":"เกาะหินปูนรูปแท่งคล้ายตะปูปักลงทะเล ในอ่าวที่เป็นอุทยานแห่งชาติ เคยเป็นฉากภาพยนตร์สายลับปี 2517","tag_hint":"terrain"},{"type":"text","role":"hint","text":"ไม่ได้อยู่อำเภอเมือง แต่อยู่ในอำเภอที่ชื่อขึ้นต้นว่า “ตะกั่ว” (และไม่ใช่ตะกั่วป่า)","tag_hint":"district"}],"reveal":{"image":{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/Phang_Nga_Bay%2C_Koh_Tapu%2C_Thailand.jpg/1280px-Phang_Nga_Bay%2C_Koh_Tapu%2C_Thailand.jpg","file":"Phang Nga Bay, Koh Tapu, Thailand.jpg","credit":"Vyacheslav Argenberg","license":"CC BY 4.0","license_url":"https://creativecommons.org/licenses/by/4.0","source_url":"https://commons.wikimedia.org/wiki/File:Phang_Nga_Bay,_Koh_Tapu,_Thailand.jpg","focus":"30% 50%","source":"commons"},"facts":{"ชื่อ":"เขาตะปู (เกาะเจมส์บอนด์) และเขาพิงกัน","ที่ตั้ง":"อุทยานแห่งชาติอ่าวพังงา ท้องที่ตำบลกะไหล อำเภอตะกั่วทุ่ง จังหวัดพังงา","จุดเด่น":"เกาะหินปูนขนาดเล็กทรงแท่งคล้ายตะปูยักษ์ อยู่ในเวิ้งอ่าวด้านเหนือของเขาพิงกัน ชมได้จากเรือหรือจากหาดของเขาพิงกัน · เขาพิงกันเป็นภูเขาที่แยกเป็นสองซีกพิงกัน","ช่วงที่เหมาะไป":"ราว พ.ย.–เม.ย. อากาศแจ่มและทะเลสงบ · พ.ค.–ต.ค. ฝนชุกและคลื่นลมแรง","ความเป็นมา":"ใช้ถ่ายทำภาพยนตร์เจมส์ บอนด์ ตอน “เพชฌฆาตปืนทอง” (The Man with the Golden Gun) ปี 2517 จึงได้ชื่อเกาะเจมส์บอนด์ · อุทยานแห่งชาติอ่าวพังงาประกาศเมื่อ 29 เม.ย. 2524"},"reasoning":"เกาะหินปูนรูปตะปูกลางอ่าว → เขาตะปู อ่าวพังงา · อันดามันเหนือภูเก็ต → พังงา · อำเภอขึ้นต้น “ตะกั่ว” ที่ไม่ใช่ตะกั่วป่า → อ.ตะกั่วทุ่ง","sources":[{"title":"ไทยพีบีเอส: รู้จัก “เขาเจมส์บอนด์” ต.กะไหล อ.ตะกั่วทุ่ง","url":"https://www.thaipbs.or.th/news/content/302973"},{"title":"ผู้จัดการ: ฉากเจมส์ บอนด์ ปี 2517 และเขาพิงกัน","url":"https://mgronline.com/travel/detail/9660000117046"},{"title":"KTC: ทะเลอันดามันเที่ยวช่วง พ.ย.–เม.ย.","url":"https://www.ktc.co.th/article/travel-guide/thailand/beach-travel-off-hurricane-season"},{"title":"Phang Nga Guide Book: ประกาศอุทยานฯ 29 เม.ย. 2524 และช่วงฝนชุก","url":"https://issuu.com/phuketemagazine/docs/phang-nga_guide_book_2013_-_issuu/17"}]},"schedule_date":null,"verified_by":null,"verified_at":null,"note":"ร่าง V2 — ข้อมูลค้นจากแหล่งที่ระบุ รอทีมตรวจทาน · ภาพลิงก์ตรงจาก Wikimedia Commons (ชื่อไฟล์ในลิงก์ภาพมีชื่อสถานที่ ถ้าอัปโหลดภาพเข้าระบบหลังบ้านจะได้ชื่อไฟล์กลาง) · คำตอบคือ อ.ตะกั่วทุ่ง ไม่ใช่ อ.เมืองพังงา (ไทยพีบีเอสระบุ ต.กะไหล อ.ตะกั่วทุ่ง · บางเว็บระบุ ต.กระโสม แต่ก็อยู่ อ.ตะกั่วทุ่ง เช่นกัน)","status":"draft","published_at":null}$j$::jsonb),
  ('q-travel-0009', 'สถานที่ท่องเที่ยว', 'draft', $j${"id":"q-travel-0009","category":"สถานที่ท่องเที่ยว","topic":"วัดมหาธาตุ สุโขทัย","answer":"TH6401","cards":[{"type":"image","role":"main","tag_hint":null,"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Wat_Mahathat%2C_Sukhothai_Historical_Park.jpg/1280px-Wat_Mahathat%2C_Sukhothai_Historical_Park.jpg","credit":"Gary Todd","license":"Public domain","license_url":"","source_url":"https://commons.wikimedia.org/wiki/File:Wat_Mahathat,_Sukhothai_Historical_Park.jpg","focus":"52% 55%","source":"commons"},{"type":"text","role":"hint","text":"อยู่ภาคกลางตอนบน (ตามการแบ่ง 6 ภาค) ในจังหวัดที่มีอุทยานประวัติศาสตร์มรดกโลกอยู่ถึงสองแห่ง","tag_hint":"region"},{"type":"text","role":"hint","text":"เจดีย์ประธานทรงดอกบัวตูม (ทรงพุ่มข้าวบิณฑ์) อยู่กลางเมืองเก่าที่มีกำแพงและคูน้ำล้อมรอบ","tag_hint":"religion_culture"},{"type":"text","role":"hint","text":"อยู่ในตำบลที่ชื่อบอกตรง ๆ ว่าเป็น “เมืองเก่า” ในอำเภอเมืองของจังหวัด","tag_hint":"district"}],"reveal":{"image":{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Wat_Mahathat%2C_Sukhothai_Historical_Park.jpg/1280px-Wat_Mahathat%2C_Sukhothai_Historical_Park.jpg","file":"Wat Mahathat, Sukhothai Historical Park.jpg","credit":"Gary Todd","license":"Public domain","license_url":"","source_url":"https://commons.wikimedia.org/wiki/File:Wat_Mahathat,_Sukhothai_Historical_Park.jpg","focus":"52% 55%","source":"commons"},"facts":{"ชื่อ":"วัดมหาธาตุ อุทยานประวัติศาสตร์สุโขทัย","ที่ตั้ง":"ตำบลเมืองเก่า อำเภอเมืองสุโขทัย จังหวัดสุโขทัย","จุดเด่น":"เจดีย์ประธานทรงพุ่มข้าวบิณฑ์ (ดอกบัวตูม) เอกลักษณ์ศิลปะสุโขทัย ล้อมด้วยเจดีย์อีก 8 องค์ · ขนาบด้วยพระอัฏฐารส พระพุทธรูปยืนสูง 18 ศอก · ในวัดมีเจดีย์กว่า 200 องค์","ช่วงที่เหมาะไป":"ช่วงงานประเพณีลอยกระทง เผาเทียน เล่นไฟ ที่อุทยานประวัติศาสตร์สุโขทัย (ราว ต.ค.–พ.ย. ตามวันลอยกระทงของแต่ละปี)","ความเป็นมา":"วัดสำคัญที่สุดกลางเมืองเก่าสุโขทัย · พ.ศ. 2496 เริ่มขุดแต่งที่วัดมหาธาตุเป็นแห่งแรก · พ.ศ. 2534 ขึ้นทะเบียนมรดกโลก “เมืองประวัติศาสตร์สุโขทัยและเมืองบริวาร” ร่วมกับศรีสัชนาลัยและกำแพงเพชร"},"reasoning":"เจดีย์ทรงดอกบัวตูม + เสาศิลาแลง → ศิลปะสุโขทัย · มรดกโลกสองแห่งในจังหวัด → สุโขทัย · ตำบลเมืองเก่า → อ.เมืองสุโขทัย","sources":[{"title":"ไทยรัฐ: หน้าวัดมหาธาตุ อุทยานประวัติศาสตร์สุโขทัย ต.เมืองเก่า อ.เมืองสุโขทัย (งานลอยกระทง 2568)","url":"https://www.thairath.co.th/news/local/localbusiness/2888230"},{"title":"TrueID: เจดีย์ทรงพุ่มข้าวบิณฑ์ เจดีย์ราย 8 องค์ พระอัฏฐารส","url":"https://travel.trueid.net/detail/aykXModZnkv6"},{"title":"ศิลปวัฒนธรรม: พ.ศ. 2496 ขุดแต่งวัดมหาธาตุเป็นแห่งแรก","url":"https://www.silpa-mag.com/history/article_15707"},{"title":"วารสารวิชาการ (ThaiJO): ขึ้นทะเบียนมรดกโลก พ.ศ. 2534","url":"https://so01.tci-thaijo.org/index.php/artsjournal_ssru/article/download/282092/180321/1153776"}]},"schedule_date":null,"verified_by":null,"verified_at":null,"note":"ร่าง V2 — ข้อมูลค้นจากแหล่งที่ระบุ รอทีมตรวจทาน · ภาพลิงก์ตรงจาก Wikimedia Commons (ชื่อไฟล์ในลิงก์ภาพมีชื่อสถานที่ ถ้าอัปโหลดภาพเข้าระบบหลังบ้านจะได้ชื่อไฟล์กลาง)","status":"draft","published_at":null}$j$::jsonb),
  ('q-travel-0010', 'สถานที่ท่องเที่ยว', 'draft', $j${"id":"q-travel-0010","category":"สถานที่ท่องเที่ยว","topic":"หาดคลองพร้าว เกาะช้าง","answer":"TH2307","cards":[{"type":"image","role":"main","tag_hint":null,"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Klong_Prao_Beach%2C_west_coast_of_Ko_Chang_Island%2C_Thailand.jpg/1280px-Klong_Prao_Beach%2C_west_coast_of_Ko_Chang_Island%2C_Thailand.jpg","credit":"Vyacheslav Argenberg","license":"CC BY 4.0","license_url":"https://creativecommons.org/licenses/by/4.0","source_url":"https://commons.wikimedia.org/wiki/File:Klong_Prao_Beach,_west_coast_of_Ko_Chang_Island,_Thailand.jpg","focus":"50% 45%","source":"commons"},{"type":"text","role":"hint","text":"อยู่ภาคตะวันออก ในจังหวัดชายแดนติดกัมพูชาที่อยู่ปลายสุดของภาค","tag_hint":"region"},{"type":"text","role":"hint","text":"หาดทรายบนเกาะที่ใหญ่เป็นอันดับ 2 ของไทย เกาะมีภูเขาสูงและป่าทึบ หาดฝั่งนี้หันไปทางพระอาทิตย์ตก","tag_hint":"terrain"},{"type":"text","role":"hint","text":"อำเภอนี้เป็นเกาะทั้งอำเภอ และชื่ออำเภอเดียวกับชื่อเกาะ (ไม่ใช่เกาะกูด)","tag_hint":"district"}],"reveal":{"image":{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Klong_Prao_Beach%2C_west_coast_of_Ko_Chang_Island%2C_Thailand.jpg/1280px-Klong_Prao_Beach%2C_west_coast_of_Ko_Chang_Island%2C_Thailand.jpg","file":"Klong Prao Beach, west coast of Ko Chang Island, Thailand.jpg","credit":"Vyacheslav Argenberg","license":"CC BY 4.0","license_url":"https://creativecommons.org/licenses/by/4.0","source_url":"https://commons.wikimedia.org/wiki/File:Klong_Prao_Beach,_west_coast_of_Ko_Chang_Island,_Thailand.jpg","focus":"50% 45%","source":"commons"},"facts":{"ชื่อ":"หาดคลองพร้าว เกาะช้าง","ที่ตั้ง":"ชายฝั่งตะวันตกของเกาะช้าง อำเภอเกาะช้าง จังหวัดตราด","จุดเด่น":"หาดทรายยาวริมทะเลเปิดฝั่งตะวันตก ชมพระอาทิตย์ตก มีคลองพร้าวไหลออกทะเล · น้ำตกคลองพลูอยู่ห่างไปราว 2–3 กม.","ช่วงที่เหมาะไป":"ราว พ.ย.–เม.ย. นอกช่วงมรสุม ทะเลสงบกว่า","ความเป็นมา":"เกาะช้างเป็นเกาะใหญ่อันดับ 2 ของไทยรองจากภูเก็ต จุดสูงสุดคือยอดเขาสลักเพชร 743 เมตร · อยู่ในอุทยานแห่งชาติหมู่เกาะช้าง ประกาศเมื่อ พ.ศ. 2525 เป็นอุทยานแห่งชาติลำดับที่ 45"},"reasoning":"หาดทรายยาว + ภูเขาป่าทึบบนเกาะ → เกาะใหญ่ทะเลตะวันออก · ตราด ติดกัมพูชา → เกาะช้าง · อำเภอชื่อเดียวกับเกาะ → อ.เกาะช้าง","sources":[{"title":"ไทยโพสต์: เกาะช้าง เกาะใหญ่อันดับ 2 รองจากภูเก็ต ยอดเขาสลักเพชร 743 ม.","url":"https://www.thaipost.net/news-update/760083/"},{"title":"Grab: หาดฝั่งตะวันตกของเกาะช้างหันออกทะเลเปิด ได้พระอาทิตย์ตก","url":"https://www.grab.com/th/blog/%E0%B8%97%E0%B8%B5%E0%B9%88%E0%B9%80%E0%B8%97%E0%B8%B5%E0%B9%88%E0%B8%A2%E0%B8%A7%E0%B9%80%E0%B8%81%E0%B8%B2%E0%B8%B0%E0%B8%8A%E0%B9%89%E0%B8%B2%E0%B8%87/"},{"title":"KTC: ทะเลตะวันออกเที่ยวช่วง พ.ย.–เม.ย.","url":"https://www.ktc.co.th/article/travel-guide/thailand/beach-travel-off-hurricane-season"},{"title":"Wikipedia (EN): Mu Ko Chang National Park ประกาศ พ.ศ. 2525 ลำดับที่ 45","url":"https://en.wikipedia.org/wiki/Mu_Ko_Chang_National_Park"},{"title":"Wongnai: หาดคลองพร้าว ใกล้น้ำตกคลองพลู","url":"https://www.wongnai.com/attractions/336483gh-%E0%B8%AB%E0%B8%B2%E0%B8%94%E0%B8%84%E0%B8%A5%E0%B8%AD%E0%B8%87%E0%B8%9E%E0%B8%A3%E0%B9%89%E0%B8%B2%E0%B8%A7"}]},"schedule_date":null,"verified_by":null,"verified_at":null,"note":"ร่าง V2 — ข้อมูลค้นจากแหล่งที่ระบุ รอทีมตรวจทาน · ภาพลิงก์ตรงจาก Wikimedia Commons (ชื่อไฟล์ในลิงก์ภาพมีชื่อสถานที่ ถ้าอัปโหลดภาพเข้าระบบหลังบ้านจะได้ชื่อไฟล์กลาง)","status":"draft","published_at":null}$j$::jsonb)
